```bash
cd /home/vscode/nullness-benchmarks/jadx && sed -i '20,26s@super(lambdaInfo, insn, InvokeType.CUSTOM, instanceCall, isRange);@super(lambdaInfo, insn, InvokeType.CUSTOM, instanceCall, isRange);
		this.implMthInfo = lambdaInfo;
		this.callInsn = new InsnNode(InsnType.NOP, 0);@;24,26s@super(mth, invokeType, argsCount);@super(mth, invokeType, argsCount);
		this.implMthInfo = mth;
